parts.text:
{
  "tom_tat": "Mo hinh du doan mau nay thuoc lop DDoS voi muc do tu tin rat cao, trong khi lop DoS dung o vi tri thu hai nhung co khoang cach chenh lech rat lon. Dac trung IAT dong vai tro ho tro manh nhat lam tang gia tri dau ra cua lop nay.",
  "lop_du_doan": "DDoS",
  "so_sanh_hai_lop": {
    "lop_thu_hai": "DoS",
    "khoang_cach_nho": false,
    "dien_giai": "Khoang cach chenh lech giua hai lop dung dau rat lon va co flag khoang cach nho tat, tuy nhien dieu nay khong co nghia la dam bao du doan chinh xac ma chi phan anh dau ra hien tai cua mo hinh."
  },
  "tong_hop_shap": {
    "ho_tro_manh_nhat": "IAT",
    "phan_doi_manh_nhat": null,
    "dien_giai": "Trong nam dac trung hang dau, IAT la yeu to ho tro manh nhat lam tang gia tri du doan, trong khi khong co dac trung nao trong nhom nay mang lai tac dong phan doi am."
  },
  "giai_thich_dac_trung": [
    {
      "ten_dac_trung": "IAT",
      "huong_tac_dong": "tang",
      "dien_giai": "Day la yeu to ho tro noi bat nhat trong top nam, dong gop lon vao viec thuc day dau ra cua lop duoc giai thich."
    },
    {
      "ten_dac_trung": "Protocol Type",
      "huong_tac_dong": "tang",
      "dien_giai": "Tac dong nay cung chieu nhung co gia tri nho hon dang ke so voi yeu to dan dau."
    },
    {
      "ten_dac_trung": "Magnitue",
      "huong_tac_dong": "tang",
      "dien_giai": "Dong gop duong bo sung giup tang cuong xac suat du doan theo huong tich cuc."
    },
    {
      "ten_dac_trung": "Number",
      "huong_tac_dong": "tang",
      "dien_giai": "Yeu to nay mang lai mot su ho tro nho hon trong nhom nam dac trung hang dau."
    },
    {
      "ten_dac_trung": "rst_count",
      "huong_tac_dong": "tang",
      "dien_giai": "Day la dac trung co tac dong tang nho nhat trong nhom cac yeu to dang duoc xem xet."
    }
  ],
  "de_xuat_kiem_tra": [
    {
      "nguon_du_lieu": "Nhật ký lưu lượng mạng",
      "noi_dung_can_kiem_tra": "Kiem tra su dong thoi cua nhieu nguon den cung dich vu neu he thong co ghi nhan dia chi va thoi gian.",
      "muc_dich": "Doi chieu bieu hien cua luu luong de lam ro bo phan du lieu dang duoc xu ly."
    },
    {
      "nguon_du_lieu": "Nhật ký tài nguyên dịch vụ",
      "noi_dung_can_kiem_tra": "Doi chieu luu luong voi tinh trang tai nguyên va kha nang phuc vu cua he thong.",
      "muc_dich": "Danh gia them ngu canh hoat dong ma khong tu dat ra cac nguong phat hien moi."
    }
  ],
  "gioi_han": [
    "Cac gia tri SHAP chi giai thich dau ra cua mo hinh cho mau hinh nay va khong chung minh quan he nhan qua hay tan cong thuc te.",
    "Xac suat cua mo hinh chua duoc xac minh la da hieu chinh va tong top nam dac trung chua phai la toan bo su thay doi.",
    "Giai thich nay khong duoc dung de thuc hien cac hanh dong tu dong nhu chan IP hay thay doi cau hinh he thong."
  ]
}

